Read Table 1 visit dates by student, then for each Table 2 row find the latest visit date strictly before that student’s submission date, and write the resulting datetime into the answer cell.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title if vals.active is not None else "Sheet1"
vws = vals[sheet_name]
wws = wb[sheet_name]

def to_dt(x):
    if x is None:
        return None
    if isinstance(x, datetime):
        return x
    if isinstance(x, date):
        return datetime(x.year, x.month, x.day)
    if isinstance(x, (int, float)):
        try:
            return datetime(1899, 12, 30) + timedelta(days=float(x))
        except Exception:
            return None
    if isinstance(x, str):
        s = x.strip()
        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%d-%b-%y",
            "%d-%b-%Y",
            "%m/%d/%Y",
            "%d/%m/%Y",
        ):
            try:
                return datetime.strptime(s, fmt)
            except Exception:
                pass
    return None

visits = []
for r in range(2, vws.max_row + 1):
    sid = vws.cell(row=r, column=1).value
    vd = to_dt(vws.cell(row=r, column=3).value)
    if sid is not None and vd is not None:
        visits.append((str(sid).strip(), vd))

max_row = max(vws.max_row, wws.max_row)
for r in range(2, max_row + 1):
    sid = vws.cell(row=r, column=8).value
    sub = to_dt(vws.cell(row=r, column=9).value)

    if sid is None and sub is None:
        continue

    if sid is not None and sub is not None:
        key = str(sid).strip()
        best = None
        for s, d in visits:
            if s == key and d < sub:
                if best is None or d > best:
                    best = d
        wws.cell(row=r, column=10).value = best

print("sheet:", sheet_name)
print("visit rows:", len(visits))
print("J2:", wws.cell(row=2, column=10).value)

wb.save(OUT)
